/** FNV-1a, enough to recognize the watcher echo of our own writes. */
function hashContent(content: string) {
    let hash = 0x811c9dc5
    for (let index = 0; index < content.length; index += 1) {
        hash ^= content.charCodeAt(index)
        hash = Math.imul(hash, 0x01000193)
    }

